<template><div class="rounded-md border border-adm-line bg-adm-surface px-2 py-2 focus-within:ring-2 focus-within:ring-adm-focus/30"><div class="flex flex-wrap gap-2"><span v-for="(tag,index) in modelValue" :key="tag" class="inline-flex items-center gap-1 rounded-full bg-adm-info-bg px-2.5 py-1 text-xs text-adm-info-ink">{{ tag }}<button type="button" :aria-label="`Remove ${tag}`" @click="remove(index)">×</button></span><input v-model="entry" :placeholder="placeholder" class="min-w-32 flex-1 border-0 bg-transparent px-2 py-1 text-sm text-adm-ink outline-none" @keydown="handleKey" @blur="add"/></div><p v-if="suggestions.length" class="mt-2 flex flex-wrap gap-1 border-t border-adm-line pt-2"><button v-for="item in suggestions" :key="item" class="rounded px-2 py-1 text-xs text-adm-ink-muted hover:bg-adm-surface-2" type="button" @click="choose(item)">{{ item }}</button></p></div></template>
<script setup lang="ts">import { computed, ref } from 'vue';const props=withDefaults(defineProps<{modelValue:string[];options?:string[];placeholder?:string}>(),{options:()=>[],placeholder:'Type and press Enter'});const emit=defineEmits<{ 'update:modelValue':[value:string[]] }>();const entry=ref('');const suggestions=computed(()=>{const term=entry.value.trim().toLowerCase();return term?props.options.filter(item=>item.toLowerCase().includes(term)&&!props.modelValue.includes(item)).slice(0,5):[]});function add(){const value=entry.value.trim();if(value&&!props.modelValue.includes(value))emit('update:modelValue',[...props.modelValue,value]);entry.value=''}function choose(value:string){emit('update:modelValue',[...props.modelValue,value]);entry.value=''}function remove(index:number){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index))}function handleKey(event:KeyboardEvent){if(event.key==='Enter'||event.key===','){event.preventDefault();add()}else if(event.key==='Backspace'&&!entry.value&&props.modelValue.length)remove(props.modelValue.length-1)}</script>
